here = Path(__file__).parent / "dub"
here.mkdir(exist_ok=True)
for lang, voice, seg in (("hi", "hi-IN-MadhurNeural", HI), ("pt", "pt-BR-AntonioNeural", PT), ("es", "es-MX-JorgeNeural", ES)):
    assert len(seg) == 30, lang
    (here / f"{lang}.json").write_text(json.dumps({"voice": voice, "rate": "+0%", "segments": seg}, ensure_ascii=False, indent=1), encoding="utf-8")
print("dubs written")
